package dev.fenn.imessage.registration

import kotlin.test.Test
import kotlin.test.assertContentEquals

/**
 * Synthetic LCG-seeded vectors for the SignState::sign port ([NacSign]); expected sig16 values
 * generated by the verified Python model (sig_hand.py sign_sig16 — session 21; see WORKLOG).
 * Inputs: LCG(1103515245, 12345, little-endian dwords) — no capture-derived bytes.
 */
class NacSignTest {

    private class SignVector(
        val label: String,
        val body576: String,
        val rand16: String,
        val blob480: String,
        val sig16: String,
    )

    private val vectors = listOf(
        SignVector(
            "lcg-101",
            "",
            "a76f0335549ca560fd571dd9f2bcfbac",
            "",
            "deb0d8abb9ee3f6c9d5cd696955b66db",
        ),
        SignVector(
            "lcg-2024",
            "",
            "6e8ca2490f7f136c9cdb9d09a539c8a7",
            "",
            "dc2f658fce2e8f2747dda92dd1ff96c7",
        ),
        SignVector(
            "lcg-90210",
            "",
            "6064861b192d0eadde011d3bbf9f9fd1",
            "",
            "fdd96429c83a964f8f800c4f5b109e6b",
        ),
        SignVector(
            "edge-7-norand",
            "",
            "00000000000000000000000000000000",
            "",
            "a9569d4508e3415a7d9206c3a6cf8e25",
        ),
        SignVector(
            "edge-8-rand-zeroblob",
            "",
            "0ef2f84f2f8493ab3cca6f2bc5939f34",
            "",
            "5f7b04163f44e800282b20c5d7c395a7",
        ),
    )

    private fun hex(s: String): ByteArray =
        ByteArray(s.length / 2) { ((Character.digit(s[it * 2], 16) shl 4) or
            Character.digit(s[it * 2 + 1], 16)).toByte() }

    @Test
    fun signMatchesModel() {
        for (v in vectors) {
            val sig = NacSign.sign(hex(v.body576), hex(v.rand16), hex(v.blob480))
            assertContentEquals(hex(v.sig16), sig, "vector ${v.label}")
        }
    }
}
